/**
 * Cloudflare Pages worker for the static build (out/_worker.js). Generated by
 * scripts/build-cloudflare.mjs, which fills in the two data blocks below.
 *
 * A static export has no Next.js server, so the URL behaviours that src/proxy.ts and
 * next.config.ts provide on a Node host are done here instead, the same way:
 *
 *   /path/                        301  /path
 *   the 35 Webflow redirects      301  final page, chains resolved
 *   /blog?56e6ea54_page=2         the stored collection-list page, URL unchanged
 *   /blog/~page/…                 404  (internal location, never served under its own URL)
 *   anything else                 the static file; unknown URLs get 404.html with status 404
 *
 * On a *.pages.dev address every page also gets "X-Robots-Tag: noindex": the preview must never
 * be indexed as a copy of signalmash.com. Pointing a real domain at the project lifts that.
 */

/** [from, to] pairs, from src/lib/site/redirects.json */
const REDIRECTS = new Map(__REDIRECTS__);
/** "path?listId_page=N" for every stored collection-list page */
const PAGED = new Set(__PAGED__);

const PAGED_PARAM = /^([0-9a-f]+)_page$/;

function finalTarget(path) {
  let to = REDIRECTS.get(path);
  for (let hops = 0; REDIRECTS.has(to) && hops < 10; hops++) to = REDIRECTS.get(to);
  return to;
}

function withHeaders(response, url) {
  const res = new Response(response.body, response);
  if (url.hostname.endsWith(".pages.dev")) res.headers.set("X-Robots-Tag", "noindex");
  return res;
}

const worker = {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (path.length > 1 && path.endsWith("/")) {
      url.pathname = path.replace(/\/+$/, "") || "/";
      return Response.redirect(url.toString(), 301);
    }

    const to = finalTarget(path);
    if (to) return Response.redirect(new URL(to + url.search, url).toString(), 301);

    if (path.split("/").includes("~page")) {
      const missing = await env.ASSETS.fetch(new URL("/404.html", url));
      return withHeaders(new Response(missing.body, { status: 404, headers: missing.headers }), url);
    }

    for (const [name, value] of url.searchParams) {
      const listId = name.match(PAGED_PARAM)?.[1];
      if (!listId || !PAGED.has(`${path}?${name}=${value}`)) continue;
      const stored = new URL(`${path === "/" ? "" : path}/~page/${listId}/${value}`, url);
      return withHeaders(await env.ASSETS.fetch(stored), url);
    }

    return withHeaders(await env.ASSETS.fetch(request), url);
  },
};

export default worker;
